"use strict";
GUIDE_DATA_VI.sections.push({"id":"g115","part":12,"title":"Các Kỹ thuật Đánh giá","blocks":[{"level":1,"text":"Việc lựa chọn nhà cung cấp là một quy trình then chốt đòi hỏi tính khách quan, công bằng và các thực hành đạo đức"},{"level":1,"text":"Để lựa chọn nhà cung cấp một cách khách quan, một hội đồng đánh giá có thể sử dụng nhiều kỹ thuật đánh giá nhà cung cấp"},{"level":2,"text":"Phương pháp đánh giá và các tiêu chí lựa chọn nguồn (source selection criteria) được xác định trước khi gửi Yêu cầu Đề xuất (Request for Proposal - RFP) để đảm bảo quy trình lựa chọn nhà cung cấp công bằng"},{"level":2,"text":"Một số kỹ thuật đánh giá"},{"level":2,"text":"Giá trị Tốt nhất so với Chi phí Thấp nhất (Best Value vs Lowest Cost)"},{"level":2,"text":"Phân tích Chi phí - Lợi ích (Cost-benefit Analysis)"},{"level":1,"text":"Khi đánh giá một nhà cung cấp, điều quan trọng là xem xét liệu họ có đủ năng lực đáp ứng các yêu cầu của hợp đồng hay không"},{"level":2,"text":"Năng lực Sản xuất (Physical Capacity)"},{"level":2,"text":"Đề cập đến khả năng của nhà cung cấp trong việc sản xuất khối lượng hàng hóa hoặc dịch vụ yêu cầu, bao gồm số đơn vị bán ra, giờ tư vấn hoặc bất kỳ thước đo liên quan nào khác"},{"level":2,"text":"Việc đánh giá năng lực sản xuất cũng nên xem xét hoạt động kinh doanh tổng thể của nhà cung cấp"},{"level":2,"text":"Hãy cân nhắc nguy cơ trì hoãn hoặc hủy bỏ nếu xung đột lịch trình phát sinh"},{"level":2,"text":"Việc đánh giá năng lực sản xuất nên tính đến cả dự báo tăng trưởng hiện tại và dài hạn"},{"level":1,"text":"Ngoài năng lực sản xuất, việc đánh giá sự ổn định tài chính của nhà cung cấp cũng rất cần thiết"},{"level":2,"text":"Đánh giá Ổn định Tài chính (Financial Stability Evaluation)"},{"level":2,"text":"Bao gồm việc đánh giá sức khỏe tài chính hoặc khả năng tồn tại tổng thể của nhà cung cấp"},{"level":2,"text":"Việc đánh giá tài chính nên bao gồm việc rà soát các mục sau"},{"level":2,"text":"Báo cáo Tài chính (Financial Statements)"},{"level":2,"text":"Tài liệu Tín dụng (Credit Documentation)"},{"level":2,"text":"Tài liệu Công khai (Public Documentation)"},{"level":2,"text":"Hãy xem xét cơ quan quản trị của nhà cung cấp để hiểu cách tài chính công ty được quản lý"},{"level":1,"text":"Việc xét đủ điều kiện của một nhà cung cấp bao gồm việc đánh giá khả năng đáp ứng nhu cầu của tổ chức mua hàng"},{"level":2,"text":"Quy trình đánh giá này yêu cầu các nhà cung cấp chứng minh năng lực cung cấp hàng hóa hoặc dịch vụ đáp ứng các tiêu chuẩn yêu cầu"},{"level":2,"text":"Việc xét đủ điều kiện có thể bao gồm việc đánh giá tình trạng cơ sở vật chất của nhà cung cấp, cũng như chuyên môn và trình độ của nhân viên họ"},{"level":1,"text":"Các Kỹ thuật Đánh giá Độ phù hợp (Fit Evaluation Techniques)"},{"level":2,"text":"Buổi Trình diễn của Nhà cung cấp (Vendor Demonstration)"},{"level":2,"text":"Buổi tương tác nơi nhà cung cấp trình bày giải pháp của họ"},{"level":2,"text":"Cách tiếp cận Kỹ thuật (Technical Approach)"},{"level":2,"text":"Bao gồm việc so sánh các hồ sơ dự thầu của nhà cung cấp với các yêu cầu của dự án"},{"level":2,"text":"Các nhà cung cấp chào sản phẩm vượt quá yêu cầu sẽ không được điểm cao hơn, và họ không cạnh tranh trực tiếp với nhau"},{"level":2,"text":"Tham chiếu (References)"},{"level":2,"text":"Việc kiểm tra tham chiếu được thực hiện với các khách hàng khác của nhà cung cấp"},{"level":1,"text":"Chuyên gia mua sắm hỏi về trải nghiệm của khách hàng với nhà cung cấp, sự tương tác của họ, công nghệ được sử dụng và hiệu suất, bao gồm khả năng phản hồi, chất lượng công việc, hiệu suất đúng hạn và quản lý chi phí"}]},{"id":"g116","part":12,"title":"Hợp đồng Mua sắm","blocks":[{"level":1,"text":"3 Loại Hợp đồng Chính (3 Main Types of Contracts)"},{"level":2,"text":"Hợp đồng Trọn gói (Fixed-Price Contract - Lump Sum Contract)"},{"level":2,"text":"Thiết lập một mức giá cố định cho một phạm vi công việc cố định và đặt phần lớn rủi ro hợp đồng lên nhà cung cấp"},{"level":2,"text":"Hợp đồng trọn gói phù hợp khi phạm vi của hợp đồng không thay đổi"},{"level":2,"text":"3 Loại Hợp đồng Trọn gói (3 Types of Fixed-Price Contracts)"},{"level":2,"text":"Trọn gói Cứng (Firm Fixed-Price - FFP)"},{"level":2,"text":"Một mô hình trong đó người mua đồng ý trả một mức giá cố định cho một sản phẩm cụ thể hoặc một nhóm sản phẩm"},{"level":2,"text":"Hợp đồng FFP phù hợp cho các sản phẩm được xác định rõ với đặc tả cụ thể"},{"level":2,"text":"Trọn gói cộng Phí Khuyến khích (Fixed-Price Incentive Fee - FPIF)"},{"level":2,"text":"Người mua có thể thêm các khoản khuyến khích vào hợp đồng trọn gói"},{"level":2,"text":"Các khoản khuyến khích có thể dựa trên chất lượng, an toàn hoặc các mục tiêu có thể đo lường khác"},{"level":2,"text":"Hiệu suất có thể đo lường được là rất quan trọng vì nó cho phép cả hai bên thống nhất lịch trình thanh toán"},{"level":2,"text":"Hợp đồng FPIF hoạt động tốt nhất khi người mua có ngân sách cho các mục tiêu kéo giãn (stretch goals)"},{"level":2,"text":"Trọn gói có Điều chỉnh Giá theo Kinh tế (Fixed-Price with Economic Price Adjustment - FP-EPA)"},{"level":2,"text":"Một hợp đồng trọn gói tính đến chi phí lạm phát"},{"level":2,"text":"Hợp đồng Chi phí cộng thêm (Cost-Plus Contract) / Hợp đồng Hoàn trả Chi phí (Cost-Reimbursable Contract)"},{"level":2,"text":"Hoàn trả cho nhà cung cấp mọi chi phí nguồn lực phát sinh khi hoàn thành công việc và cộng thêm một khoản phí để bao phủ biên lợi nhuận của nhà cung cấp"},{"level":2,"text":"Người mua chịu trách nhiệm đối với bất kỳ sự quản lý nguồn lực kém hiệu quả nào từ phía nhà cung cấp"},{"level":2,"text":"Việc theo dõi chi phí hiệu quả là rất quan trọng để kiểm soát chi phí trong hợp đồng hoàn trả chi phí"},{"level":2,"text":"Chi phí cộng thêm Phí Thưởng (Cost-Plus Award Fee - CPAF)"},{"level":2,"text":"Khoản phí bổ sung được trao dựa trên hiệu suất của nhà cung cấp trong dự án"},{"level":2,"text":"Hợp đồng CPAF khuyến khích nhà cung cấp đáp ứng nhu cầu của người mua bằng cách đưa ra một khoản phí thưởng nếu nhà cung cấp vượt kỳ vọng"},{"level":2,"text":"Hợp đồng Chi phí cộng thêm Phí Khuyến khích (Cost-Plus Incentive Fee - CPIF)"},{"level":2,"text":"Hợp đồng đưa ra cho nhà cung cấp một khoản khuyến khích để hoàn thành dự án trong các hoàn cảnh cụ thể"},{"level":2,"text":"Hợp đồng Thời gian và Vật liệu (Time-and-Material - T&M)"},{"level":2,"text":"Thanh toán cho số giờ làm việc thực tế của nhà cung cấp theo đơn giá giờ đã được xác định trước"},{"level":2,"text":"Người mua ưu tiên hợp đồng T&M khi họ tin tưởng vào khả năng hoàn thành dự án trong ngân sách của nhà cung cấp"},{"level":2,"text":"Hợp đồng Chi phí cộng thêm Phần trăm Chi phí (Cost-Plus Percentage of Cost - CPPC)"},{"level":2,"text":"Nhà cung cấp nhận một khoản phí bằng một phần trăm của mọi chi phí"},{"level":2,"text":"Hợp đồng CPPC có lợi khi người mua muốn có sự linh hoạt để thay đổi vật liệu hoặc điều chỉnh phạm vi công việc khi dự án tiến triển"},{"level":2,"text":"Hợp đồng Lai (Hybrid Contract)"},{"level":2,"text":"Như đơn giá và thời gian-vật liệu"},{"level":2,"text":"Nó phù hợp để mua các công việc lặp lại khi số lượng hoặc phạm vi chưa được biết tại thời điểm bắt đầu dự án"},{"level":2,"text":"Hợp đồng thời gian và vật liệu (T&M) phù hợp cho các dự án có chi phí cố định và phạm vi linh hoạt"},{"level":2,"text":"Người mua ưu tiên hợp đồng T&M để kiểm soát chi phí tối đa nhưng vẫn giữ được sự linh hoạt trong quá trình thực hiện dự án"}]},{"id":"g117","part":12,"title":"Điều khoản Hợp đồng","blocks":[{"level":1,"text":"Có một số điều khoản hợp đồng mà bạn cần biết trước khi bắt đầu mua sắm giải pháp, như bảo hành (warranties) và thỏa thuận không tiết lộ (non-disclosure agreements)"},{"level":1,"text":"Việc đưa bảo hành vào thỏa thuận mua sắm có thể giảm thiểu rủi ro cho người mua bằng cách cung cấp sự đảm bảo của nhà cung cấp trong việc xử lý mọi khuyết tật"},{"level":1,"text":"Bảo hành (Warranty)"},{"level":2,"text":"Phác thảo khoảng thời gian mà nhà cung cấp dự kiến sản phẩm không có lỗi và quy định hướng xử lý trong trường hợp hỏng hóc"},{"level":2,"text":"Các Yếu tố Chung của Bảo hành (Common Elements of Warranty)"},{"level":2,"text":"Thời hạn (Length)"},{"level":2,"text":"Thời gian bảo hành được quy định, thường kéo dài trong một khoảng thời gian xác định, như một năm"},{"level":2,"text":"Phạm vi (Scope)"},{"level":2,"text":"Bảo hành thường bao phủ các khuyết tật phát sinh từ quy trình sản xuất, như việc ăng-ten Wi-Fi đột ngột hỏng trong điện thoại di động"},{"level":2,"text":"Khắc phục (Remediation)"},{"level":2,"text":"Nhà cung cấp phác thảo hướng xử lý trong trường hợp có khuyết tật, thường bao gồm hoàn tiền, thay thế hoặc cả hai"},{"level":2,"text":"Các Giới hạn và Loại trừ (Limitations and Exclusions)"},{"level":2,"text":"Nhà cung cấp quy định ranh giới trách nhiệm của mình, bao gồm các giới hạn và các tình huống bị loại trừ"},{"level":2,"text":"Khởi đầu (Commencement)"},{"level":2,"text":"Điều khoản khởi đầu liên quan đến các dự án, như bảo hành triển khai phần mềm trong thỏa thuận mua sắm cung cấp khắc phục miễn phí cho các sự cố"},{"level":1,"text":"Thỏa thuận Không tiết lộ (Non-Disclosure Agreements)"},{"level":2,"text":"Cho phép trao đổi thông tin nhạy cảm hoặc có giá trị với một mức độ tin cậy nhất định rằng nó sẽ không bị tiết lộ"},{"level":2,"text":"Một số tình huống có thể yêu cầu NDA, bao gồm"},{"level":2,"text":"Phát triển sản phẩm mới"},{"level":2,"text":"Nếu cả hai bên cùng hợp tác để tạo ra một sản phẩm hoặc thiết kế mới, họ nên ký một NDA"},{"level":2,"text":"Thông tin không công khai"},{"level":2,"text":"Nếu nhà cung cấp có quyền truy cập vào bất kỳ thông tin nào không được công bố công khai, một NDA có thể bảo vệ dữ liệu độc quyền và nhạy cảm"},{"level":2,"text":"Cơ sở vật chất (Facilities)"},{"level":2,"text":"Nếu nhà cung cấp sẽ có quyền truy cập vào cơ sở vật chất của bạn nơi họ có thể thấy các quy trình, thiết bị hoặc thông tin độc quyền, hãy yêu cầu một NDA"},{"level":2,"text":"Tư vấn (Consulting)"},{"level":2,"text":"Các nhà tư vấn nên ký một NDA cho khách hàng của mình vì quy trình tư vấn liên quan đến việc chia sẻ thông tin không công khai"},{"level":1,"text":"Sau khi các hợp đồng đã được ký và dự án bắt đầu triển khai, PM đảm nhận vai trò chính trong việc quản lý mối quan hệ với nhà cung cấp"},{"level":1,"text":"PM có sự hiểu biết sâu sắc hơn về các sản phẩm bàn giao của dự án, các tiêu chuẩn chất lượng và kỳ vọng của khách hàng"},{"level":1,"text":"PM sẽ tham gia vào một số hoạt động quản lý nhà cung cấp trong suốt dự án"},{"level":2,"text":"Quy tắc Tương tác (Rules of Engagement)"},{"level":2,"text":"Các thỏa thuận vận hành quy định cách nhà cung cấp và đội dự án sẽ hợp tác để thực hiện một dự án"},{"level":2,"text":"Các quy tắc tương tác rất quan trọng đối với bất kỳ dự án nào, đặc biệt là những dự án có sự tham gia của các nhóm cá nhân đa dạng chưa từng làm việc cùng nhau trước đây"},{"level":2,"text":"Giám sát Hiệu suất (Performance Monitoring)"},{"level":2,"text":"PM cũng có khả năng giám sát và đánh giá hiệu suất có thể định lượng được của nhà cung cấp, như việc tuân thủ các SLA của họ"},{"level":2,"text":"Điều quan trọng là hợp tác với nhà cung cấp để điều chỉnh các mục tiêu nếu cần thiết, vì các mục tiêu ban đầu thường có thể quá tham vọng"},{"level":2,"text":"Phê duyệt Sản phẩm Bàn giao (Approval of Deliverables)"},{"level":2,"text":"Bao gồm việc rà soát kỹ lưỡng công việc được gửi, đảm bảo nó đáp ứng các tiêu chuẩn chất lượng của dự án"},{"level":2,"text":"Mỗi sản phẩm bàn giao nên góp phần vào việc hoàn thành tổng thể của dự án, và bất kỳ công việc nào không làm được điều đó đều phải được đánh giá. Quản lý Việc thực hiện Dự án (Managing Project Execution)"}]},{"id":"g118","part":13,"title":"Quản lý Việc thực hiện Dự án","blocks":[{"level":1,"text":"Sự bắt đầu của phase thực hiện (Execution) đánh dấu một điểm quan trọng trong dự án"},{"level":1,"text":"Trong các phase khám phá (discovery), khởi tạo (initiation) và lập kế hoạch (planning), người quản lý dự án dẫn dắt và thúc đẩy hầu hết các hoạt động của dự án"},{"level":1,"text":"Để theo dõi thông tin này một cách hiệu quả, đội nhóm phải lập kế hoạch cách họ sẽ tổ chức nó và cam kết tuân theo quy trình"},{"level":1,"text":"Người quản lý dự án chịu trách nhiệm giám sát tiến độ của dự án"},{"level":2,"text":"Họ thu thập dữ liệu, phân tích báo cáo và đo lường tiến độ, báo cáo cho các bên liên quan và đảm bảo giao tiếp diễn ra suôn sẻ"},{"level":1,"text":"Người quản lý dự án nhận các yêu cầu thay đổi, phân tích chúng và điều chỉnh kế hoạch dự án cho phù hợp"},{"level":1,"text":"Người quản lý dự án tạo điều kiện để đội nhóm bàn giao kế hoạch, đưa ra sự hỗ trợ tích cực và phản hồi mang tính xây dựng, duy trì động lực (momentum), loại bỏ các trở ngại và tin tưởng các thành viên đội nhóm trong việc bàn giao công việc của họ"}]},{"id":"g119","part":13,"title":"Động lực Dự án","blocks":[{"level":1,"text":"Quản lý một dự án giống như giám sát một hệ thống rộng lớn, phức tạp với nhiều thành phần"},{"level":2,"text":"Điều này đòi hỏi sự kết hợp giữa kỹ năng quản lý dự án và kỹ năng lãnh đạo, cùng với mong muốn chân thành hỗ trợ người khác"},{"level":1,"text":"Để thiết lập và duy trì động lực dự án (project momentum), hãy cân nhắc triển khai các phương pháp sau"},{"level":2,"text":"Bắt đầu Mạnh mẽ (Starting Strong)"},{"level":2,"text":"Thiết lập Nhịp độ (Setting the Pace)"},{"level":2,"text":"Hướng về Phía trước (Looking Forward)"},{"level":2,"text":"Tạo Động lực cho Đội nhóm (Motivating the Team)"},{"level":1,"text":"Để đảm bảo thành công của dự án, điều then chốt là bắt đầu với một tầm nhìn rõ ràng"},{"level":2,"text":"Điều này có nghĩa là hiểu tại sao dự án lại quan trọng và nó cần đạt được gì"},{"level":1,"text":"Các nhà tài trợ dự án (project sponsors), các bên liên quan và thành viên đội nhóm đều phải hiểu tại sao công ty lại chọn đầu tư vào dự án này hơn tất cả các dự án khác"},{"level":1,"text":"PM cũng thiết lập nhịp độ bằng cách thực thi các thời hạn và thiết lập các kỳ vọng rõ ràng mà đội nhóm sẽ thực hiện"},{"level":2,"text":"Họ dự đoán và loại bỏ các trở ngại để giữ dự án đi đúng tiến độ"},{"level":2,"text":"Họ hiểu giá trị của dự án hơn bất kỳ ai và đảm bảo đội nhóm cũng thấu hiểu tầm quan trọng của nó"},{"level":1,"text":"Nó cũng là việc tạo ra một môi trường dự án thuận lợi không làm cạn kiệt năng lượng của họ"},{"level":1,"text":"PM nên thu thập phản hồi từ đội nhóm để cải thiện hệ thống mà họ đang làm việc"}]},{"id":"g120","part":13,"title":"Ma trận Truy vết Yêu cầu (Requirements Traceability Matrix - RTM)","blocks":[{"level":1,"text":"Ma trận Truy vết Yêu cầu (Requirements Traceability Matrix - RTM)"},{"level":2,"text":"Tài liệu lập bản đồ và theo dõi mối quan hệ giữa yêu cầu, thiết kế, phát triển, kiểm thử và triển khai"},{"level":2,"text":"RTM giúp đảm bảo mọi yêu cầu của dự án đều được đáp ứng và dự án được bàn giao đúng tiến độ, đúng ngân sách"},{"level":2,"text":"RTM cũng cung cấp cái nhìn minh bạch về tiến độ dự án"},{"level":1,"text":"Khả năng truy vết (Traceability)"},{"level":2,"text":"Khả năng theo dõi đường đi của một thứ gì đó"},{"level":2,"text":"Khả năng truy vết rất quan trọng để giải quyết vấn đề và cập nhật hệ thống"},{"level":2,"text":"Trong một số trường hợp, khả năng truy vết là yêu cầu pháp lý"},{"level":1,"text":"Khả năng truy vết hai chiều của RTM rất quan trọng vì nó cho phép truy vết công việc từ yêu cầu đến các bài kiểm thử và ngược lại"},{"level":2,"text":"Truy vết xuôi (Forward Traceability)"},{"level":2,"text":"Đi từ yêu cầu gốc đến các bài kiểm thử tạo ra từ đó"},{"level":2,"text":"Truy vết ngược (Backward Traceability)"},{"level":2,"text":"Bắt đầu từ các bài kiểm thử và quay ngược lại về yêu cầu"},{"level":1,"text":"RTM mang lại nhiều lợi ích khác cho dự án"},{"level":2,"text":"Hữu ích cho phân tích tác động vì nó tập trung mọi thông tin yêu cầu"},{"level":2,"text":"Giúp xác định dự án có đáp ứng yêu cầu hay không"},{"level":2,"text":"Đơn giản hóa quy trình kiểm toán và chất lượng"},{"level":2,"text":"Xác định yêu cầu nào chưa được đáp ứng"}]},{"id":"g121","part":13,"title":"Công cụ Theo dõi Tiến độ (Progress Tracking Tools)","blocks":[{"level":1,"text":"Ứng dụng quản lý dự án cho phép theo dõi dự án và lập kế hoạch cho các hoạt động cần thiết"},{"level":1,"text":"Theo dõi Tiến độ (Monitor Progress)"},{"level":2,"text":"Cho phép nhà quản lý dự án theo dõi tiến độ dự án và đảm bảo các công việc đang được hoàn thành đúng tiến độ"},{"level":1,"text":"Cải thiện Phân bổ Nguồn lực (Improve Resource Allocation)"},{"level":2,"text":"Nhà quản lý dự án có thể phân bổ nguồn lực và đảm bảo các thành viên nhóm làm việc hiệu quả"},{"level":1,"text":"Ước lượng Chính xác Tiến độ Dự án (Accurately Estimate Project Timelines)"},{"level":2,"text":"Việc theo dõi thời gian hoàn thành công việc giúp nhà quản lý dự án đưa ra ước lượng chính xác cho các dự án tương lai"},{"level":1,"text":"Tăng cường Truyền thông (Enhance Communication)"},{"level":2,"text":"Được dùng để tạo báo cáo và các hình thức trực quan hóa khác cung cấp thông tin hữu ích về tiến độ dự án"},{"level":1,"text":"Ứng dụng Theo dõi Thời gian (Application for Time Tracking)"},{"level":2,"text":"Theo dõi chi tiết thời gian cần thiết để hoàn thành công việc"},{"level":1,"text":"Ứng dụng Theo dõi Dự án và Thời gian (Project and Time Tracking Application)"},{"level":2,"text":"Bao gồm các tính năng hữu ích như tạo báo cáo, giúp đơn giản hóa quy trình truyền thông"},{"level":2,"text":"Quản lý dự án (Project Management)"},{"level":2,"text":"Phân rã công việc, tổ chức nguồn lực, quản lý phụ thuộc và kiểm soát tiến độ dự án"},{"level":2,"text":"Theo dõi thời gian (Time Tracking)"},{"level":2,"text":"Lập kế hoạch ngày làm việc và báo cáo tiến độ"},{"level":1,"text":"Bảng công việc (Task Board)"},{"level":2,"text":"Công cụ trực quan để theo dõi công việc"}]},{"id":"g122","part":13,"title":"Kiểm soát Phiên bản (Version Control)","blocks":[{"level":1,"text":"Phần mềm kiểm soát phiên bản được các nhóm phát triển phần mềm và DevOps sử dụng để tối ưu hóa quy trình phát triển và phát hành"},{"level":2,"text":"Chúng lưu lại những gì đã thay đổi, thay đổi lúc nào và ai đã thay đổi"},{"level":1,"text":"Mã nguồn của một sản phẩm phần mềm rất lớn và bao gồm nhiều mối phụ thuộc lẫn nhau"},{"level":1,"text":"Các công cụ kiểm soát phiên bản chạy nền, theo dõi mọi thay đổi đối với mã nguồn"},{"level":1,"text":"Không có kiểm soát phiên bản, gánh nặng truy vết sẽ đổ lên vai lập trình viên"},{"level":1,"text":"Việc kiểm thử cũng có thể mất nhiều thời gian hơn, vì xác định nguyên nhân bài kiểm thử thất bại phải lục tìm trong các file offline của lập trình viên để tìm ra thay đổi"},{"level":1,"text":"Kiểm soát phiên bản là công cụ thiết yếu đối với bất kỳ nhà quản lý dự án CNTT nào"}]},{"id":"g123","part":13,"title":"Nhật ký (Logs)","blocks":[{"level":1,"text":"Nhật ký vấn đề (issue log), nhật ký lỗi (defect log) và nhật ký thay đổi (change log) quan trọng đối với nhà quản lý dự án CNTT vì nhiều lý do"},{"level":2,"text":"Nhật ký cho phép nhà quản lý dự án CNTT theo dõi tiến độ dự án"},{"level":2,"text":"Nhật ký cũng giúp chúng ta nhận ra các mẫu hình trong các loại vấn đề, lỗi và thay đổi xảy ra"},{"level":2,"text":"Nhật ký vấn đề và nhật ký lỗi giúp nhà quản lý dự án CNTT nhanh chóng xác định và giải quyết vấn đề và lỗi"},{"level":2,"text":"Nhật ký thay đổi ghi lại mọi thay đổi đối với dự án"},{"level":2,"text":"Khi các thay đổi được thực hiện"},{"level":2,"text":"Ai thực hiện chúng"},{"level":2,"text":"Tại sao"},{"level":1,"text":"Nhật ký Vấn đề (Issue Log)"},{"level":2,"text":"Công cụ theo dõi và quản lý các vấn đề phát sinh trong dự án"},{"level":2,"text":"Mỗi vấn đề được ghi lại với mô tả, ngày phát hiện và người phát hiện"},{"level":2,"text":"Các trường phổ biến trong nhật ký vấn đề bao gồm"},{"level":2,"text":"Số vấn đề (Issue Number)"},{"level":2,"text":"Mô tả (Description)"},{"level":2,"text":"Mức ưu tiên (Priority)"},{"level":2,"text":"Tác động (Impact)"},{"level":2,"text":"Người báo cáo (Raised By — người báo cáo vấn đề)"},{"level":2,"text":"Người chịu trách nhiệm (Owner — người chịu trách nhiệm khắc phục vấn đề)"},{"level":2,"text":"Trạng thái (Status)"},{"level":2,"text":"Ngày phát hiện (Date Found)"},{"level":2,"text":"Ngày đóng (Date Closed)"},{"level":2,"text":"Ghi chú (Comments)"},{"level":2,"text":"Nhật ký vấn đề đảm bảo các vấn đề không bị bỏ sót và giúp ưu tiên chúng dựa trên tác động đến dự án"},{"level":1,"text":"Nhật ký Lỗi (Defect Log)"},{"level":2,"text":"Dùng chủ yếu trong các dự án phần mềm để theo dõi và quản lý các trường hợp sản phẩm được xây dựng để đáp ứng yêu cầu nhưng lại không làm được điều đó"},{"level":2,"text":"Nó cần cung cấp đủ thông tin để kỹ sư nghiên cứu, tái hiện và khắc phục lỗi"},{"level":2,"text":"Bài kiểm thử thất bại (Failed test)"},{"level":2,"text":"Môi trường hoặc đầu vào (Environment or inputs)"},{"level":2,"text":"Hành vi của hệ thống (System's behavior)"},{"level":2,"text":"Ảnh chụp màn hình (Screenshots)"},{"level":2,"text":"Bản ghi hình (Recordings)"},{"level":2,"text":"File nhật ký (Log files)"},{"level":2,"text":"Các trường phổ biến trong nhật ký lỗi bao gồm"},{"level":2,"text":"Số lỗi (Defect Number)"},{"level":2,"text":"Mô tả (Description)"},{"level":2,"text":"Bài kiểm thử thất bại (Failed Test(s))"},{"level":2,"text":"Cách tái hiện (How to Reproduce)"},{"level":2,"text":"Mức ưu tiên (Priority)"},{"level":2,"text":"Tác động (Impact)"},{"level":2,"text":"Người phát hiện (Found By)"},{"level":2,"text":"Người chịu trách nhiệm (Owner — người chịu trách nhiệm khắc phục lỗi)"},{"level":2,"text":"Trạng thái (Status)"},{"level":2,"text":"Ngày phát hiện (Date Found)"},{"level":2,"text":"Ngày khắc phục (Date Fixed)"},{"level":2,"text":"Ghi chú (Comments)"},{"level":2,"text":"Nhật ký lỗi đảm bảo các lỗi được khắc phục và sản phẩm đáp ứng yêu cầu"},{"level":1,"text":"Nhật ký Thay đổi (Change Log)"},{"level":2,"text":"Bản ghi các điều chỉnh đối với kế hoạch dự án"},{"level":2,"text":"Thay đổi là điều thường gặp trong mọi dự án, bao gồm"},{"level":2,"text":"Thêm tính năng mới (Addition of a new feature)"},{"level":2,"text":"Một thành viên rời nhóm (Departure of a team member)"},{"level":2,"text":"Các trường phổ biến trong nhật ký thay đổi bao gồm"},{"level":2,"text":"Số thay đổi (Change Number)"},{"level":2,"text":"Mô tả (Description)"},{"level":2,"text":"Loại yêu cầu (Type of Request)"},{"level":2,"text":"Mức ưu tiên (Priority)"},{"level":2,"text":"Tác động (Impact)"},{"level":2,"text":"Người yêu cầu (Requested By)"},{"level":2,"text":"Người chịu trách nhiệm (Owner)"},{"level":2,"text":"Trạng thái (Status)"},{"level":2,"text":"Ngày yêu cầu hoặc xác định (Date of Request or Identification)"},{"level":2,"text":"Ngày hoàn thành (Date of Completion)"},{"level":2,"text":"Ghi chú (Comments)"},{"level":1,"text":"PM thường dùng một sổ đăng ký (register) duy nhất để ghi lại rủi ro, vấn đề, thay đổi và lỗi"}]},{"id":"g124","part":13,"title":"Biểu đồ Burnup và Burndown (Burnup and Burndown Charts)","blocks":[{"level":1,"text":"Các cập nhật định kỳ được chuẩn bị trước giúp phản ứng nhanh chóng và hiệu quả"},{"level":1,"text":"Biểu đồ burnup và burndown là công cụ hữu ích để quản lý phạm vi và thời gian của dự án"},{"level":2,"text":"Nó theo dõi hai giá trị chính"},{"level":2,"text":"Công việc mục tiêu (Target Work)"},{"level":2,"text":"Công việc thực tế (Actual Work)"},{"level":1,"text":"Biểu đồ Burnup (Burnup Chart)"},{"level":2,"text":"Theo dõi tổng lượng công việc đã hoàn thành mỗi ngày"},{"level":2,"text":"Biểu đồ burnup hiệu quả nhất khi phạm vi dự án cố định nhưng thời gian linh hoạt"},{"level":1,"text":"Biểu đồ Burndown (Burndown Chart)"},{"level":2,"text":"Theo dõi lượng công việc còn lại mỗi ngày"},{"level":2,"text":"Biểu đồ burndown phù hợp nhất cho các dự án có thời gian cố định"}]},{"id":"g125","part":13,"title":"Biểu đồ Velocity và Throughput (Velocity and Throughput Charts)","blocks":[{"level":1,"text":"Biểu đồ Velocity (Velocity Chart)"},{"level":2,"text":"Đo số story point mà nhóm có thể hoàn thành trong một sprint hoặc iteration nhất định"},{"level":2,"text":"Biểu đồ velocity giúp nhà quản lý dự án CNTT đo lường và quản lý năng suất của nhóm theo thời gian"},{"level":1,"text":"Biểu đồ Throughput (Throughput Chart)"},{"level":2,"text":"Đo số mục công việc hoàn thành trong mỗi iteration, bất kể độ phức tạp hay nỗ lực cần thiết"},{"level":2,"text":"Nhóm có thể dùng dữ liệu để xác định năng lực, ưu tiên các mục công việc và lập kế hoạch khối lượng công việc cho các sprint sắp tới"},{"level":2,"text":"Dùng biểu đồ throughput, PM CNTT có thể theo dõi hiệu suất của nhóm và đặt mục tiêu cho các sprint sắp tới"},{"level":1,"text":"Cả biểu đồ velocity và throughput đều có giá trị đối với các nhóm agile"},{"level":2,"text":"Cung cấp cách đo lường tiến độ và hiệu suất của nhóm"},{"level":2,"text":"Xác định các điểm cần cải thiện, điều chỉnh khối lượng công việc và lập kế hoạch năng lực cho các sprint tương lai"},{"level":2,"text":"Duy trì nhịp độ làm việc ổn định bằng cách đặt mục tiêu dựa trên hiệu suất trong quá khứ"},{"level":2,"text":"Giúp các nhóm agile làm việc hiệu quả, bàn giao dự án đúng hạn và cải thiện hiệu suất"}]},{"id":"g126","part":13,"title":"Các Cuộc họp (Meetings)","blocks":[{"level":1,"text":"Cuộc họp Tình trạng Nhóm / Cuộc họp Touchpoint của Nhóm (Team Status Meeting / Team Touchpoint Meeting)"},{"level":2,"text":"Cuộc họp định kỳ dùng để cập nhật tiến độ tổng thể của dự án và giải quyết mọi vấn đề"},{"level":2,"text":"Các cuộc họp tình trạng nhóm là cuộc họp làm việc"},{"level":2,"text":"Chương trình họp hiệu quả nên bao gồm các chủ đề sau"},{"level":2,"text":"Các action item đang mở (Open action items)"},{"level":2,"text":"Cập nhật tình trạng (Status updates)"},{"level":2,"text":"Cập nhật công việc (Task updates)"},{"level":2,"text":"Rủi ro và vấn đề đang mở (Open risks and issues)"},{"level":2,"text":"Rủi ro và vấn đề mới (New risks and issues)"},{"level":2,"text":"Hiệu suất liên quan đến phạm vi, thời gian và chi phí (Performance related to scope, time, and cost)"},{"level":2,"text":"Cập nhật về phân công RACI (Responsible, Accountable, Consulted, and Informed) (Updates on RACI assignments)"},{"level":2,"text":"Dashboard chứa thông tin chi tiết về dự án và trông giống như một giao diện đơn giản"},{"level":1,"text":"Cuộc họp Lập kế hoạch Sprint (Sprint Planning Meeting)"},{"level":2,"text":"Nhóm sẽ lập kế hoạch công việc cho sprint sắp tới"},{"level":2,"text":"Đầu mỗi sprint, nhóm sẽ họp lại để lập kế hoạch công việc cho sprint sắp tới"},{"level":2,"text":"Đặt năng lực sprint (sprint capacity) dựa trên throughput hoặc velocity trong quá khứ"},{"level":2,"text":"Xem xét các mục ưu tiên hàng đầu trong backlog và chia nhỏ chúng thành các mục công việc nhỏ hơn"},{"level":2,"text":"Chương trình cuộc họp lập kế hoạch sprint nên bao gồm các nội dung sau"},{"level":2,"text":"Xem xét các mục tiêu của dự án (Review of project goals)"},{"level":2,"text":"Thảo luận về mọi vấn đề, lỗi hoặc thay đổi có thể ảnh hưởng đến kế hoạch dự án (Discussion of any issues, defects, or changes that could affect the project plan)"},{"level":2,"text":"Đặt mục tiêu sprint (velocity hoặc throughput) (Setting the sprint target)"},{"level":2,"text":"Xây dựng sprint backlog (Development of the sprint backlog)"},{"level":1,"text":"Cuộc họp với Các bên Liên quan (Stakeholder Meeting)"},{"level":2,"text":"Được tổ chức để báo cáo tiến độ tổng thể của dự án, thu thập phản hồi và nhấn mạnh các sản phẩm bàn giao sắp tới"},{"level":1,"text":"Cuộc họp với Bên Liên quan Bên ngoài (External Stakeholder Meeting)"},{"level":2,"text":"Cần sự kiềm chế và thái độ tích cực, tập trung vào thành công, và chỉ thảo luận các sản phẩm bàn giao và mốc quan trọng mà bên ngoài thấy được"},{"level":2,"text":"Chương trình cuộc họp với bên liên quan bên ngoài bao gồm"},{"level":2,"text":"Tình trạng dự án (Project status)"},{"level":2,"text":"Các bản phát hành sắp tới (Upcoming releases)"},{"level":2,"text":"Các mốc quan trọng và hạn chót lớn (Major milestones and deadlines)"},{"level":2,"text":"Các bước tiếp theo (Next steps)"},{"level":2,"text":"Thu thập phản hồi (Feedback solicitation)"},{"level":1,"text":"Cuộc họp với Bên Liên quan Nội bộ (Internal Stakeholder Meeting)"},{"level":2,"text":"Bao gồm các trở ngại nghiêm trọng, rủi ro và vấn đề, các mốc quan trọng và hạn chót lớn, hiệu suất phạm vi, thời gian và chi phí, các bước tiếp theo và thu thập phản hồi"},{"level":1,"text":"Cuộc họp Có điều kiện (Conditional Meeting)"},{"level":2,"text":"Diễn ra theo yêu cầu hoặc khi cần sự hỗ trợ từ một nhóm cụ thể"},{"level":2,"text":"3 loại Cuộc họp Có điều kiện (3 Types of Conditional Meeting)"},{"level":2,"text":"Cuộc họp Cổng Giai đoạn (Phase Gate Meeting)"},{"level":2,"text":"Được tổ chức cuối mỗi giai đoạn của dự án để xem xét các sản phẩm bàn giao, đánh giá tiến độ dự án và quyết định có tiếp tục dự án hay không"},{"level":2,"text":"Cuộc họp Kiểm soát Thay đổi (Change Control Meeting)"},{"level":2,"text":"Được tổ chức để xem xét và phê duyệt mọi đề xuất thay đổi phạm vi, tiến độ hoặc ngân sách của dự án"},{"level":2,"text":"Báo cáo Đặc biệt (Ad Hoc Reporting)"},{"level":2,"text":"Báo cáo được thực hiện theo nhu cầu phát sinh"}]},{"id":"g127","part":13,"title":"Đưa ra Phản hồi (Providing Feedback)","blocks":[{"level":1,"text":"Trách nhiệm chính của PM là tối ưu hóa hiệu suất dự án bằng cách theo dõi tiến độ và thực hiện các điều chỉnh cần thiết đối với kế hoạch quản lý dự án"},{"level":1,"text":"Phản hồi Tích cực (Positive Feedback)"},{"level":2,"text":"Ghi nhận những đóng góp hiệu quả cho dự án"},{"level":1,"text":"Phản hồi Tiêu cực (Negative Feedback)"},{"level":2,"text":"Nêu bật các lĩnh vực cần cải thiện"},{"level":1,"text":"2 Quy tắc Vàng (2 Golden Rules)"},{"level":2,"text":"Đối xử với người khác như cách bạn muốn được đối xử (Treat others as you want to be treated)"},{"level":2,"text":"Khen ngợi công khai, nhắc nhở riêng tư (Praise in public and correct in private)"},{"level":1,"text":"Vòng lặp phản hồi (feedback loop) là một chu trình trong đó bạn kiểm tra và cải thiện một hệ thống"},{"level":2,"text":"Thu thập phản hồi (Gather Feedback)"},{"level":2,"text":"Phân tích phản hồi (Analyze Feedback)"},{"level":2,"text":"Hành động theo phản hồi (Act on Feedback)"},{"level":2,"text":"Theo dõi kết quả (Follow Up)"},{"level":1,"text":"Các nguồn phản hồi mà bạn có thể rút ra thông tin chi tiết, gắn với bước đầu tiên của quy trình phản hồi"},{"level":2,"text":"Chỉ số Hiệu suất (Performance Metrics)"},{"level":2,"text":"Tạo các báo cáo hiệu suất dự án có thể cung cấp phản hồi giá trị"},{"level":2,"text":"Nhận xét của Bên liên quan (Stakeholder Comments)"},{"level":2,"text":"Các bên liên quan sẽ đưa phản hồi trong các cuộc họp, email và các cuộc trò chuyện không chính thức"},{"level":2,"text":"Quan sát (Observation)"},{"level":2,"text":"Chú ý cách mỗi người đóng góp cho sản phẩm và ghi lại những điểm có thể cải thiện"},{"level":2,"text":"Phản hồi từ Đồng đội (Teammate Feedback)"},{"level":2,"text":"Thu thập nhận xét từ các đồng đội qua hệ thống phản hồi chính thức hoặc các cuộc họp một-một"},{"level":2,"text":"Bài học Kinh nghiệm (Lessons Learned)"},{"level":2,"text":"Theo dõi phản hồi và tìm các xu hướng củng cố các phản hồi khác mà bạn đã thu thập"},{"level":1,"text":"Đưa ra phản hồi là một kỹ năng"},{"level":1,"text":"Khi ai đó làm tốt, hãy cụ thể và khen ngợi hành động của họ"},{"level":1,"text":"Hãy nhạy cảm với các phản ứng có thể xảy ra"},{"level":1,"text":"Nếu phản hồi liên quan đến vấn đề pháp lý, an toàn hoặc nhân sự, bộ phận liên quan và những bên được nêu trong chính sách công ty của bạn cần được thông báo"},{"level":1,"text":"Phản hồi kịp thời có giá trị hơn phản hồi chậm trễ"},{"level":1,"text":"Chia sẻ phản hồi gần thời điểm sự việc để thành viên nhóm học hỏi và điều chỉnh hành vi cho phù hợp"},{"level":1,"text":"Một số phản hồi nên thảo luận trong nhóm, chẳng hạn phản hồi chức năng về một mục công việc"},{"level":1,"text":"Một số phản hồi khác có thể cần trao đổi riêng tư, vì vậy hãy cân nhắc dùng các phương thức bất đồng bộ như email"},{"level":1,"text":"Hãy đặt mình vào vị trí người nhận và nghĩ về cách bạn muốn nhận phản hồi"},{"level":1,"text":"Hãy thoải mái khi đưa ra phản hồi (Resolve Issues)"}]},{"id":"g128","part":13,"title":"Giải quyết Vấn đề (Resolve Issues)","blocks":[{"level":1,"text":"Rủi ro (Risk)"},{"level":2,"text":"Các sự kiện tương lai tiềm ẩn có thể xảy ra hoặc không"},{"level":1,"text":"Quy trình quản lý vấn đề gồm nhiều bước"},{"level":2,"text":"Xác định vấn đề và ghi vào nhật ký vấn đề (Identify the issue and record it in an issue log)"},{"level":2,"text":"Phân tích vấn đề, xác định nguyên nhân và tác động, và ưu tiên (Analyze the issue, determine the cause and impact, and prioritize)"},{"level":2,"text":"Giải quyết vấn đề bằng cách quyết định hành động cần thực hiện và triển khai chúng (Resolve the issue by deciding which actions to take and implementing them)"},{"level":2,"text":"Theo dõi vấn đề để đảm bảo nó đã được giải quyết và đóng trong nhật ký vấn đề (Monitor the issue to ensure it is resolved and closed in the issue log)"},{"level":1,"text":"Để quản lý vấn đề hiệu quả, điều quan trọng là thiết lập quy trình theo dõi vấn đề và các điểm leo thang"},{"level":1,"text":"Phân tích vấn đề bao gồm thực hiện phân tích nguyên nhân gốc để xác định tại sao vấn đề xảy ra"},{"level":1,"text":"Có thể dùng nhiều công cụ để phân tích, bao gồm biểu đồ phân tán, biểu đồ run chart, biểu đồ pareto, phân tích năm lần hỏi tại sao và biểu đồ xương cá"},{"level":1,"text":"Quy trình phân tích vấn đề được dùng để xác định mức ưu tiên tương đối của một vấn đề"},{"level":2,"text":"Nên đánh giá lại vấn đề vì mức độ nghiêm trọng và tiêu chí có thể thay đổi"},{"level":2,"text":"Các yếu tố như mức độ nghiêm trọng, tính khẩn cấp, tác động đến dự án và tổ chức, leo thang vấn đề và ưu tiên vấn đề được xem xét trong phân tích"},{"level":1,"text":"Mức độ nghiêm trọng đo lường mức độ ảnh hưởng của vấn đề, trong khi tính khẩn cấp xác định cần xử lý nhanh đến đâu"},{"level":1,"text":"Sau khi giải quyết vấn đề, điều quan trọng là theo dõi chúng để đảm bảo chúng vẫn được giải quyết và phát hiện các vấn đề mới"},{"level":1,"text":"Biểu đồ Kiểm soát (Control Chart)"},{"level":2,"text":"Biểu đồ thống kê dùng để theo dõi biến động trong một quy trình"},{"level":2,"text":"Chúng bao gồm đường trung tâm, giới hạn kiểm soát trên và giới hạn kiểm soát dưới để xác định khi nào quy trình mất kiểm soát"},{"level":1,"text":"Quản lý vấn đề hiệu quả đòi hỏi văn hóa minh bạch, báo cáo vấn đề chủ động và các kênh truyền thông rõ ràng"}]},{"id":"g129","part":13,"title":"Tổng quan về Quản lý Vấn đề (Issue Management Overview)","blocks":[{"level":1,"text":"Rủi ro (Risk)"},{"level":2,"text":"Sự kiện tương lai tiềm ẩn có thể xảy ra hoặc không"},{"level":2,"text":"Rủi ro có thể tích cực hoặc tiêu cực"},{"level":1,"text":"Không phải mọi vấn đề đều được xác định trong kế hoạch quản lý rủi ro"},{"level":1,"text":"Các rủi ro chưa biết sẽ trở thành các sự kiện hiện tại (vấn đề)"},{"level":1,"text":"Quy trình quản lý vấn đề khác nhau tùy tổ chức nhưng nhìn chung gồm bốn loại lớn"},{"level":2,"text":"Xác định và ghi lại vấn đề (Identify and record issue)"},{"level":2,"text":"Phân tích vấn đề (Analyze the issue)"},{"level":2,"text":"Giải quyết vấn đề (Resolve the issue)"},{"level":2,"text":"Theo dõi và đóng vấn đề (Monitor and close the issue)"}]},{"id":"g130","part":13,"title":"Xác định Vấn đề (Identify the Issue)","blocks":[{"level":1,"text":"Nhật ký vấn đề nên được công khai để mọi thành viên nhóm và bên liên quan đều xem được tiến độ"},{"level":1,"text":"Quy trình theo dõi vấn đề đơn giản giúp vấn đề có nhiều khả năng được ghi vào nhật ký trước khi bị lãng quên"},{"level":2,"text":"Luôn đảm bảo người dùng tuân thủ các quy trình"},{"level":1,"text":"Danh sách tập trung đơn giản cho phép người ra quyết định so sánh mức ưu tiên tương đối"},{"level":2,"text":"Điều này cũng giúp bạn nhanh chóng tạo báo cáo và theo dõi các vấn đề đang mở"},{"level":1,"text":"Điểm Leo thang (Escalation Point)"},{"level":2,"text":"Sự kiện sẽ kích hoạt nhu cầu thông báo cho các cấp có thẩm quyền ngày càng cao"},{"level":1,"text":"Lộ trình leo thang thường di chuyển lên một hoặc nhiều cấp trong hệ thống quản lý ở mỗi điểm leo thang"},{"level":1,"text":"Các phụ thuộc (dependencies) là điểm leo thang tự động"},{"level":1,"text":"Đảm bảo quy trình báo cáo vấn đề dễ dùng và dễ tiếp cận"},{"level":1,"text":"Thiết lập các kênh truyền thông hiệu quả"}]},{"id":"g131","part":13,"title":"Phân tích Vấn đề (Analyze the Issue)","blocks":[{"level":1,"text":"Một vấn đề chỉ là biểu hiện bề nổi của một vấn đề nền sâu hơn"},{"level":1,"text":"Dùng các công cụ chất lượng khác nhau có thể giúp phát hiện vấn đề và xác định nguyên nhân gốc"},{"level":1,"text":"Thực hiện phân tích nguyên nhân gốc rất quan trọng để xác định tại sao vấn đề xảy ra"},{"level":1,"text":"Xem xét nhật ký vấn đề có thể giúp xác định các triệu chứng khác"},{"level":1,"text":"RCA giúp phân tích và ưu tiên vấn đề tốt hơn"},{"level":1,"text":"Giải quyết một vấn đề có thể cần nhiều hoạt động vì bạn muốn xử lý cả triệu chứng lẫn nguyên nhân gốc"},{"level":2,"text":"Biểu đồ Phân tán (Scatter Diagram)"},{"level":2,"text":"Vẽ hai biến, một biến trên trục x và biến còn lại trên trục y, mỗi lần xuất hiện của biến (x,y) được biểu thị bằng một chấm"},{"level":2,"text":"Biểu đồ hữu ích để mô tả mối tương quan giữa các biến"},{"level":2,"text":"Nó trả về một giá trị toán học \"R2\" và giá trị này dao động từ -1 đến 1"},{"level":2,"text":"Biểu đồ phân tán hiệu quả với tập dữ liệu lớn và tạo ra biểu đồ dễ đọc"},{"level":2,"text":"Biểu đồ Run (Run Chart)"},{"level":2,"text":"Đồ thị đường thể hiện dữ liệu theo thời gian"},{"level":2,"text":"Biểu đồ Pareto (Pareto Charts)"},{"level":2,"text":"Nguyên tắc Pareto cho rằng khắc phục một phần nhỏ nguyên nhân gốc có thể giải quyết hầu hết vấn đề, với quy tắc 80/20: 80% vấn đề bắt nguồn từ 20% nguyên nhân"},{"level":2,"text":"Biểu đồ Pareto có thể cho thấy công việc trễ vì sáu lý do, trong đó ba lý do chiếm phần lớn các lần trễ"},{"level":2,"text":"Ước lượng thiếu thời gian cần thiết (Underestimating time requirements)"},{"level":2,"text":"Phải chuyển sự chú ý sang công việc vận hành (Needing to divert attention to operational work)"},{"level":2,"text":"Gặp sự cố phần cứng (Experiencing hardware issues)"},{"level":2,"text":"Phân tích Năm lần hỏi Tại sao (Five-Why Analysis)"},{"level":2,"text":"Kỹ thuật giải quyết vấn đề bằng cách đặt câu hỏi \"tại sao\" để xác định nguyên nhân gốc của vấn đề"},{"level":2,"text":"Biểu đồ Xương cá (Fishbone Diagram)"},{"level":2,"text":"Đầu cá tượng trưng cho vấn đề, các xương sườn tượng trưng cho các nguyên nhân liên quan có thể"},{"level":2,"text":"Đầu cá tượng trưng cho vấn đề, các xương sườn tượng trưng cho các nguyên nhân liên quan có thể, có thể được phân loại theo 6P (chính sách - policy, quy trình - process, con người - people, nhà máy/thiết bị - plant, chương trình - program, và sản phẩm - product) hoặc các nhóm tùy chỉnh"}]},{"id":"g132","part":13,"title":"Công cụ Ưu tiên Vấn đề (Issue Prioritization Tools)","blocks":[{"level":1,"text":"Phân tích Vấn đề (Issue Analysis)"},{"level":2,"text":"Dùng để xác định mức ưu tiên tương đối của một vấn đề"},{"level":2,"text":"Nên đánh giá lại vấn đề vì hai lý do"},{"level":2,"text":"Mức độ nghiêm trọng của vấn đề có thể khác với đánh giá rủi ro, đặc biệt với các rủi ro lớn"},{"level":2,"text":"Đánh giá vấn đề theo các tiêu chí chi tiết hơn có thể hữu ích vì bạn có nhiều thông tin hơn về chúng so với các rủi ro chưa biết"},{"level":1,"text":"Nhiều yếu tố có thể được xem xét để phân tích vấn đề, tùy thuộc vào dự án và tổ chức"},{"level":2,"text":"Mức độ nghiêm trọng (Severity)"},{"level":2,"text":"Tính khẩn cấp (Urgency)"},{"level":2,"text":"Tác động (Impact)"},{"level":2,"text":"Phạm vi tác động (Scope of Impact)"},{"level":2,"text":"Leo thang vấn đề (Issue Escalation)"},{"level":2,"text":"Ưu tiên vấn đề (Issue Prioritization)"},{"level":1,"text":"Để đo mức độ nghiêm trọng của vấn đề, hãy ước lượng nó ảnh hưởng thế nào đến người dùng trung bình"},{"level":1,"text":"Vấn đề Nghiêm trọng (Critical Issue)"},{"level":2,"text":"Làm cho hệ thống hoàn toàn không thể truy cập hoặc không hoạt động"},{"level":1,"text":"Vấn đề Lớn (Major Issue)"},{"level":2,"text":"Cho phép người dùng truy cập hệ thống, nhưng một hoặc nhiều tính năng không khả dụng"},{"level":1,"text":"Vấn đề Nhỏ (Minor Issue)"},{"level":2,"text":"Không ảnh hưởng đến trải nghiệm người dùng, nhưng cần giải pháp tạm thời (workaround)"},{"level":1,"text":"Vấn đề Mức độ Thấp (Low-Severity Issue)"},{"level":2,"text":"Không ảnh hưởng đến chức năng nhưng nên được khắc phục vì thương hiệu, tính nhất quán hoặc để cải thiện trải nghiệm người dùng"},{"level":1,"text":"Tính khẩn cấp (Urgency)"},{"level":2,"text":"Thước đo tính nhạy cảm về thời gian của vấn đề, cho biết cần xử lý nhanh đến đâu"},{"level":1,"text":"Hầu hết các công ty dùng thang đo đơn giản với giới hạn thời gian cho mỗi mức"},{"level":2,"text":"Khẩn cấp Nghiêm trọng (Critical Urgency)"},{"level":2,"text":"Cần giải quyết ngay lập tức"},{"level":2,"text":"Khẩn cấp Lớn (Major Urgency)"},{"level":2,"text":"Cần giải quyết trong vài giờ"},{"level":2,"text":"Khẩn cấp Trung bình (Medium Urgency)"},{"level":2,"text":"Cần giải quyết trong vài ngày"},{"level":2,"text":"Khẩn cấp Nhỏ (Minor Urgency)"},{"level":2,"text":"Giải quyết khi thuận tiện sớm nhất"},{"level":1,"text":"Mức đo tác động định lượng mức độ ảnh hưởng của vấn đề"},{"level":1,"text":"Xem xét vấn đề sẽ tác động thế nào đến phạm vi, tiến độ hoặc ngân sách của dự án"},{"level":1,"text":"Thang đo đơn giản được dùng để đo tác động đối với dự án"},{"level":2,"text":"Cao (High)"},{"level":2,"text":"Việc hoàn thành dự án đang bị đe dọa"},{"level":2,"text":"Trung bình (Medium)"},{"level":2,"text":"Dự án có thể bị trễ"},{"level":2,"text":"Thấp (Low)"},{"level":2,"text":"Dự án sẽ không bị ảnh hưởng"},{"level":1,"text":"Đánh giá khả năng leo thang của vấn đề là một thực hành hữu ích"},{"level":2,"text":"Leo thang Vấn đề (Issue Escalation)"},{"level":2,"text":"Đảm bảo các rủi ro và vấn đề nghiêm trọng được theo dõi phù hợp"},{"level":2,"text":"Các vấn đề đã leo thang nên được ưu tiên cao hơn"},{"level":1,"text":"Thước đo ưu tiên leo thang vấn đề cũng có thể được đo bằng thang đo đơn giản như sau"},{"level":2,"text":"Cao (High)"},{"level":2,"text":"Đã có kế hoạch leo thang và đã được leo thang"},{"level":2,"text":"Trung bình (Medium)"},{"level":2,"text":"Có kế hoạch leo thang nhưng chưa kích hoạt"},{"level":2,"text":"Thấp (Low)"},{"level":2,"text":"Không có kế hoạch leo thang vấn đề"},{"level":1,"text":"Ưu tiên Vấn đề (Issue Prioritization)"},{"level":2,"text":"Bao gồm thang đo mô tả với các giá trị số đi kèm thể hiện điểm thực tế cho từng yếu tố"},{"level":2,"text":"Thông thường, điểm được sắp xếp theo thang 1-9, trong đó 9 là mức ưu tiên cao nhất"},{"level":2,"text":"Thang 1-3-9 lý tưởng để chấm ba lựa chọn, chẳng hạn thấp, trung bình và cao"},{"level":2,"text":"Thang 1-2-3 sẽ khiến hầu hết các mục đều có mức ưu tiên tương đối trung bình"},{"level":2,"text":"Có thể đạt hiệu quả tương tự với bốn giá trị bằng cách dùng thang 1-3-7-9"},{"level":2,"text":"Thang này ép buộc ra quyết định bằng cách đẩy các mục ưu tiên cao lên đầu"},{"level":1,"text":"Để ưu tiên vấn đề, bạn nên xác định các yếu tố liên quan và thêm chúng làm cột mới trong nhật ký vấn đề"},{"level":1,"text":"Tính điểm ưu tiên vấn đề tương đối bằng cách cộng điểm của từng yếu tố"}]},{"id":"g133","part":13,"title":"Giải quyết và Theo dõi Vấn đề (Resolve and Monitor the Issue)","blocks":[{"level":1,"text":"Xem xét kế hoạch leo thang để xác định vấn đề đã từng được xử lý chưa"},{"level":1,"text":"Xác định người chịu trách nhiệm vấn đề và làm theo kế hoạch leo thang để thông báo cho các bên phù hợp"},{"level":1,"text":"Người chịu trách nhiệm vấn đề chịu trách nhiệm giải quyết vấn đề"},{"level":1,"text":"Các mục ưu tiên thấp hơn có thể nhận ít sự chú ý hơn các mục ưu tiên cao hơn"},{"level":1,"text":"Các kế hoạch dự phòng giúp giải quyết vấn đề nhanh chóng bằng cách cung cấp kế hoạch ứng phó"},{"level":1,"text":"Thực thi kế hoạch dự phòng để bảo vệ tài sản và khôi phục dịch vụ"},{"level":1,"text":"Kế hoạch dự phòng giúp nhóm phục hồi và tiếp tục công việc nhanh chóng"},{"level":1,"text":"Các nhà quản lý dự án CNTT cần thực hiện nhiều hoạt động theo dõi để triển khai hiệu quả kế hoạch giải quyết vấn đề, bao gồm"},{"level":2,"text":"Theo dõi các vấn đề đã giải quyết (Monitoring resolved issues)"},{"level":2,"text":"Theo dõi các vấn đề đang mở (Monitoring open issues)"},{"level":2,"text":"Theo dõi hiệu suất dự án (Monitoring project performance)"},{"level":1,"text":"PM chịu trách nhiệm sở hữu nhật ký vấn đề và theo dõi các người chịu trách nhiệm được liệt kê"},{"level":1,"text":"Cũng quan trọng là xem xét lại điểm đánh giá thỉnh thoảng để đảm bảo chúng vẫn phản ánh thực tế"},{"level":1,"text":"Để xác minh việc giải quyết vấn đề, nhà quản lý dự án phải xác minh và phê duyệt từng giải pháp đã hoàn thành"},{"level":2,"text":"Kiểm tra mọi hậu quả không mong muốn (Check for any unintended consequences)"},{"level":2,"text":"Xác nhận đã hoàn thành mọi hành động (Confirm completion of all actions)"},{"level":2,"text":"Đảm bảo giải pháp đã xử lý được vấn đề (Ensure that the resolution addressed the problem)"},{"level":1,"text":"Theo dõi các giải pháp tạm thời (workaround) được triển khai cho từng vấn đề"},{"level":1,"text":"Nếu vấn đề tái diễn, hãy thực hiện một phân tích nguyên nhân gốc khác và nỗ lực giải quyết"},{"level":1,"text":"Bằng cách theo dõi các vấn đề đã đóng, bạn có thể xác định các xu hướng và vấn đề tái diễn, dùng để cải thiện hệ thống"},{"level":1,"text":"Đưa tóm tắt vấn đề vào tài liệu bài học kinh nghiệm"},{"level":2,"text":"Tài liệu này nên chi tiết cách nhóm tiếp cận vấn đề, họ đã học được gì và lần sau họ sẽ làm khác đi thế nào"}]},{"id":"g134","part":13,"title":"Biểu đồ Kiểm soát (Control Charts)","blocks":[{"level":1,"text":"Biểu đồ Kiểm soát (Control Charts)"},{"level":2,"text":"Biểu đồ dùng phương pháp thống kê để theo dõi biến động trong một quy trình theo thời gian"},{"level":1,"text":"Khi một quy trình hoạt động như kỳ vọng, nó được gọi là \"đang trong kiểm soát\" (\"in control\")"},{"level":1,"text":"Nếu quy trình cho thấy mức biến động không thể chấp nhận được, nó được coi là \"mất kiểm soát\" (\"out of control\")"},{"level":1,"text":"Trục hoành thể hiện thời gian hoặc trình tự, trong khi trục tung thể hiện đầu ra tương ứng"},{"level":1,"text":"Biểu đồ kiểm soát phân biệt giữa các mẫu hình có ý nghĩa thống kê trong dữ liệu và biến động thông thường"},{"level":2,"text":"Mặc dù biểu đồ run có thể trông như thể hiện xu hướng, chúng có thể gây hiểu lầm vì biến động thông thường hiện diện trong mọi quy trình"},{"level":1,"text":"Biến động Nguyên nhân Chung (Common Cause Variation)"},{"level":2,"text":"Biến động dự kiến trong một quy trình và các giới hạn của biểu đồ kiểm soát dựa trên nó"},{"level":1,"text":"Biến động Nguyên nhân Đặc biệt (Special Cause Variation)"},{"level":2,"text":"Độc nhất và làm thay đổi điều gì đó về quy trình, dẫn đến kết quả bất thường"},{"level":1,"text":"Biến động là một phần tự nhiên của mọi quy trình và không nhất thiết cho thấy hiệu suất tốt hay xấu"},{"level":1,"text":"Dùng biểu đồ kiểm soát để xác minh rằng nó đang tạo ra hiệu quả mong muốn"},{"level":1,"text":"Xác định các lĩnh vực có thể cải thiện (Control Change)"}]},{"id":"g135","part":14,"title":"Kiểm soát Thay đổi (Control Change)","blocks":[{"level":1,"text":"Kiểm soát thay đổi giúp xác định yêu cầu nào có thể trở thành một phần của dự án"},{"level":1,"text":"Kiểm soát Thay đổi (Change Control)"},{"level":2,"text":"Quy trình có hệ thống để đánh giá, phê duyệt và quản lý các đề xuất thay đổi đối với phạm vi, mục tiêu, sản phẩm bàn giao của dự án hoặc các khía cạnh chính khác"},{"level":2,"text":"Đảm bảo các thay đổi được đánh giá, lập tài liệu, ủy quyền và triển khai đúng cách, đồng thời giảm thiểu gián đoạn và duy trì sự đồng bộ của dự án"},{"level":1,"text":"Thay đổi Phạm vi (Scope Change)"},{"level":2,"text":"Sửa đổi, thêm hoặc loại bỏ các sản phẩm bàn giao, mục tiêu, yêu cầu hoặc ranh giới của dự án"},{"level":1,"text":"Phình Phạm vi (Scope Creep)"},{"level":2,"text":"Mở rộng dần dần và không kiểm soát được của phạm vi dự án vượt ra ngoài ranh giới đã định ban đầu"},{"level":1,"text":"Các Phương thức Triển khai Thay đổi CNTT Khác nhau (Different IT Change Delivery Methods)"},{"level":2,"text":"Khung giờ Bảo trì (Maintenance Windows)"},{"level":2,"text":"Bản phát hành (Releases)"},{"level":2,"text":"Thông báo cho Khách hàng (Customer Notifications)"}]},{"id":"g136","part":14,"title":"Tổng quan về Kiểm soát Thay đổi (Change Control Overview)","blocks":[{"level":1,"text":"Quy trình kiểm soát thay đổi bao gồm việc gửi yêu cầu thay đổi, các yêu cầu này được đánh giá và hoặc phê duyệt hoặc từ chối"},{"level":1,"text":"Các bước cụ thể trong quy trình kiểm soát thay đổi có thể khác nhau tùy tổ chức, nhưng nhìn chung gồm bốn giai đoạn"},{"level":2,"text":"Khởi tạo yêu cầu (Initiating the request)"},{"level":2,"text":"Đánh giá các tác động (Evaluating the impacts)"},{"level":2,"text":"Ra quyết định về kết quả (Making a decision on the outcome)"},{"level":2,"text":"Triển khai thay đổi (Implementing the change)"},{"level":1,"text":"Triển khai quy trình kiểm soát thay đổi đảm bảo dự án luôn đồng bộ với nhu cầu kinh doanh"},{"level":1,"text":"Kiểm soát thay đổi cải thiện khả năng truy vết các yêu cầu của dự án"},{"level":1,"text":"Kiểm soát thay đổi đơn giản hóa công việc và loại bỏ sự nhầm lẫn"},{"level":1,"text":"Không phải mọi thay đổi đều cần quy trình kiểm soát thay đổi chính thức"},{"level":1,"text":"Mục đích của kiểm soát thay đổi là quản lý các thay đổi đối với các baseline phạm vi, thời gian và chi phí của dự án"},{"level":1,"text":"Nhiều sự kiện có thể kích hoạt yêu cầu thay đổi trong giai đoạn thực thi dự án, bao gồm"},{"level":2,"text":"Các điểm không nhất quán (Inconsistencies)"},{"level":2,"text":"Các mục tiêu quá tham vọng (Aggressive goals)"},{"level":2,"text":"Các cải tiến của nhóm (Team improvements)"},{"level":2,"text":"Các thay đổi chiến lược (Strategic changes)"},{"level":2,"text":"Các thay đổi phạm vi (Scope changes)"},{"level":2,"text":"Các thay đổi sản phẩm (Product changes)"},{"level":1,"text":"Dự án là một hoạt động cần được quản lý"},{"level":2,"text":"Dự án (Project)"},{"level":2,"text":"Tạo ra hoặc sửa đổi sản phẩm"},{"level":2,"text":"Sản phẩm (Product)"},{"level":2,"text":"Kết quả hoặc thành phần có giá trị"},{"level":1,"text":"Thay đổi sản phẩm có thể gây ra hoặc không gây ra thay đổi trong dự án của bạn"},{"level":1,"text":"Kiểm soát thay đổi có thể giúp quản lý các điều chỉnh đối với dự án, sản phẩm hoặc hệ thống"},{"level":2,"text":"Nó đảm bảo các thay đổi:"},{"level":2,"text":"Đồng bộ với nhu cầu kinh doanh (Aligned with business needs)"},{"level":2,"text":"Cho phép các bên liên quan xem xét và phê duyệt thay đổi (Enable stakeholders to review and approve changes)"},{"level":2,"text":"Cải thiện khả năng truy vết các yêu cầu của dự án (Improve traceability for project requirements)"},{"level":1,"text":"Khác biệt giữa thay đổi dự án và thay đổi sản phẩm"},{"level":2,"text":"Thay đổi Dự án (Project Change)"},{"level":2,"text":"Luôn tác động đến dự án"},{"level":2,"text":"Thay đổi Sản phẩm (Product Change)"},{"level":2,"text":"Có thể cần hoặc không cần thay đổi dự án"},{"level":1,"text":"Quy trình kiểm soát thay đổi giúp quản lý các thay đổi một cách thận trọng và có hiểu biết hơn"}]},{"id":"g137","part":14,"title":"Thay đổi Phạm vi so với Phình Phạm vi (Scope Change vs Scope Creep)","blocks":[{"level":1,"text":"Phình Phạm vi (Scope Creep)"},{"level":2,"text":"Chỉ sự thay đổi không được phê duyệt, thường làm tăng công việc và kéo dài dự án, điều này là không mong muốn vì nó bắt đầu dùng thêm nguồn lực — thời gian, tiền bạc hoặc con người"},{"level":1,"text":"Thay đổi Phạm vi (Scope Change)"},{"level":2,"text":"Điều chỉnh dự án đã được phê duyệt, đi qua các kênh phê duyệt"},{"level":2,"text":"Thay đổi phạm vi cũng đòi hỏi đàm phán lại phạm vi, thời gian và ngân sách, và điều chỉnh bất kỳ hoặc cả ba baseline là một lựa chọn"},{"level":1,"text":"Để tránh phình phạm vi, hãy làm cho thay đổi phạm vi trở thành một khả năng"},{"level":1,"text":"Tập trung vào các công việc quan trọng nhất giúp bàn giao sản phẩm chất lượng cao"},{"level":1,"text":"Khi chúng ta triển khai các thay đổi, có các bước phải tuân theo"},{"level":2,"text":"Khởi tạo yêu cầu (Initiate the request)"},{"level":2,"text":"Đánh giá các tác động (Evaluate the impacts)"},{"level":2,"text":"Quyết định kết quả (Decide on an outcome)"},{"level":2,"text":"Triển khai thay đổi (Implement the change)"},{"level":1,"text":"Triển khai giải pháp đám mây bao gồm việc dùng hai tài liệu quan trọng"},{"level":2,"text":"Mẫu Yêu cầu Thay đổi (Change Request Form)"},{"level":2,"text":"Dùng để thu thập thông tin về một yêu cầu thay đổi duy nhất"},{"level":2,"text":"Nó bao gồm một số trường thường dùng trong các dự án CNTT"},{"level":2,"text":"Tên Dự án (Project Name)"},{"level":2,"text":"Ngày Yêu cầu (Date Requested)"},{"level":2,"text":"Mô tả (Description)"},{"level":2,"text":"Lý do Thay đổi (Reason for Change)"},{"level":2,"text":"Mức ưu tiên (Priority)"},{"level":2,"text":"Tác động (Impact)"},{"level":2,"text":"Người Yêu cầu (Requested By)"},{"level":2,"text":"Người chịu trách nhiệm (Owner)"},{"level":2,"text":"Hạn chót (Deadline(s))"},{"level":2,"text":"Ghi chú (Comments)"},{"level":2,"text":"Nhật ký Thay đổi (Change Log)"},{"level":2,"text":"Chứa mọi yêu cầu thay đổi của dự án và còn được gọi là \"Nhật ký Kiểm soát Thay đổi\" (\"Change Control Log\")"},{"level":2,"text":"Nhà quản lý dự án ghi yêu cầu thay đổi vào nhật ký thay đổi, thêm các chi tiết liên quan như ID"},{"level":1,"text":"Triển khai giải pháp đám mây bao gồm việc dùng hai tài liệu quan trọng"},{"level":1,"text":"PM phân tích yêu cầu để xác định nó sẽ ảnh hưởng thế nào đến nguồn lực, ngân sách, phạm vi và tiến độ của dự án"},{"level":1,"text":"Các yêu cầu phần cứng và phần mềm thường đòi hỏi thay đổi yêu cầu của sản phẩm"},{"level":1,"text":"PM tổng hợp mọi thông tin về yêu cầu thay đổi"},{"level":2,"text":"Thay đổi Tiến độ (Schedule Changes)"},{"level":2,"text":"Thay đổi Phạm vi (Scope Changes)"},{"level":2,"text":"Rủi ro (Risks)"},{"level":2,"text":"Yêu cầu Nguồn lực (Resource Requirements)"},{"level":2,"text":"Các Tác động Đáng chú ý (Notable Impacts)"},{"level":1,"text":"Sau khi hoàn thành phân tích tác động và xây dựng khuyến nghị, PM trình bày các phát hiện này cho người ra quyết định phù hợp chịu trách nhiệm phê duyệt hoặc từ chối thay đổi"},{"level":1,"text":"Các thay đổi vận hành thường liên quan đến công việc hàng ngày của việc vận hành dự án và có tác động tối thiểu đến chi phí, phạm vi hoặc baseline của dự án"},{"level":1,"text":"Thẩm quyền của CCB thiết lập mức độ thẩm quyền của PM đối với việc ra quyết định vận hành"},{"level":1,"text":"Các thay đổi chiến lược có ảnh hưởng vượt ra ngoài ranh giới của dự án và tác động đến tài chính, danh mục kinh doanh hoặc mục tiêu dài hạn của công ty"},{"level":1,"text":"Nhà tài trợ dự án, CCB và PMO là những người ra quyết định chiến lược cho một dự án, với ban quản lý điều hành ủy quyền ra quyết định cho các nhóm này"},{"level":1,"text":"Các thay đổi liên quan đến rủi ro cần sự tham gia của người chịu trách nhiệm rủi ro (risk owner) với tư cách là người ra quyết định"},{"level":1,"text":"Với tư cách là nhà quản lý dự án làm việc trong dự án có Hội đồng Kiểm soát Thay đổi (Change Control Board - CCB), trách nhiệm có thể giảm bớt"},{"level":2,"text":"PM vẫn sẽ tiếp nhận yêu cầu thay đổi, duy trì nhật ký, thực hiện phân tích và đưa ra khuyến nghị, CCB chính thức tiếp quản quyền sở hữu các thay đổi của dự án"},{"level":1,"text":"Sau đây là một số loại phê duyệt thay đổi phần mềm phổ biến"},{"level":2,"text":"Phê duyệt Kỹ thuật (Technical Approval)"},{"level":2,"text":"Bao gồm việc xem xét và đóng góp ý kiến từ các chuyên gia am hiểu hệ thống"},{"level":2,"text":"Quy trình đánh giá ngang hàng này có thể diễn ra dưới nhiều hình thức"},{"level":2,"text":"Xem xét Kỹ thuật (Technical Review)"},{"level":2,"text":"Xem xét Mã nguồn (Code Review)"},{"level":2,"text":"Lập trình Cặp (Pair Programming)"},{"level":2,"text":"Phê duyệt của Chủ sở hữu Sản phẩm (Product Owner Approval)"},{"level":2,"text":"Bao gồm xem xét và phê duyệt các thay đổi để xác nhận sản phẩm đáp ứng mọi yêu cầu"},{"level":2,"text":"Phê duyệt Kiến trúc (Architectural Approval)"},{"level":2,"text":"Đảm bảo sản phẩm tác động tích cực đến hệ thống"},{"level":1,"text":"Xác định các yêu cầu không khả thi về mặt kỹ thuật sớm và gắn cờ để xem xét"},{"level":1,"text":"Khi kết quả yêu cầu thay đổi đã được quyết định, nhà quản lý dự án (PM) sẽ thông báo trạng thái của thay đổi cho các bên liên quan"},{"level":1,"text":"Truyền thông nhất quán về các thay đổi của dự án tạo ra sự hiểu biết chung giữa các bên liên quan về phạm vi và tiến độ của dự án, xây dựng mối quan hệ vững chắc và quản lý kỳ vọng"},{"level":1,"text":"PM cập nhật kế hoạch dự án, tùy thuộc vào bản chất của thay đổi, bằng cách cập nhật các nội dung sau"},{"level":2,"text":"Tiến độ (Schedule)"},{"level":2,"text":"Các sản phẩm bàn giao (Deliverables)"},{"level":2,"text":"Ngân sách (Budget)"},{"level":2,"text":"Ma trận RACI (RACI Matrix)"},{"level":2,"text":"Hồ sơ kinh doanh (Business Case)"},{"level":2,"text":"Kế hoạch Quản lý Các bên Liên quan (Stakeholder Management Plan)"},{"level":1,"text":"Sau khi xác thực, PM thông báo cho các bên liên quan về thay đổi đã hoàn thành, bao gồm các cập nhật trong các cuộc họp và báo cáo định kỳ, chẳng hạn báo cáo tình trạng dự án"}]});
